const mode = flow.get("locationMode") || "city";
const apiKey = "a163ac642eeecd0bb9240cc34b74f994";
const base = "https://api.openweathermap.org/data/2.5/weather";

if (mode === "city") {
    const city = flow.get("cityInput") || "London,GB";
    msg.url = `${base}?q=${encodeURIComponent(city)}&appid=${apiKey}&units=metric`;
    // no lat/lon known yet here — map won't update in this branch
} else {
    const lat = flow.get("lat") || "51.5";
    const lon = flow.get("lon") || "-0.12";
    msg.url = `${base}?lat=${lat}&lon=${lon}&appid=${apiKey}&units=metric`;

    const delta = 0.025;
    msg.mapUrl = `https://www.openstreetmap.org/export/embed.html?bbox=${lon - delta},${lat - delta},${lon + delta},${lat + delta}&layer=mapnik&marker=${lat},${lon}`;
}

return msg;

const d = msg.payload;

if (!d || d.cod !== 200) {
    node.warn("Bad API response: " + JSON.stringify(d));
    return null;
}

// Store parsed values in flow context for other nodes to use
const weather = {
    city: d.name + ", " + d.sys.country,
    description: d.weather[0].description,
    temp: d.main.temp,
    humidity: d.main.humidity,
    pressure: d.main.pressure,
    windSpeed: d.wind.speed * 3.6,          // m/s → km/h
    windDeg: d.wind.deg,
    sunrise: new Date(d.sys.sunrise * 1000).toLocaleTimeString(),
    sunset: new Date(d.sys.sunset * 1000).toLocaleTimeString(),
    icon: d.weather[0].icon
};

flow.set("lastWeather", weather);

// Send the full object downstream
msg.payload = weather;
return msg;

const w = flow.get("lastWeather");
msg.payload = `The weather in ${w.city} is ${w.description}. Temperature is ${w.temp} degrees celsius. Humidity is ${w.humidity} percent.`;
return msg;

const weather = msg.payload;
const param = flow.get("warnParam") || "temp";
const limit = flow.get("warnLimit") || 30;
const value = weather[param];
const labels = { temp: "Temperature", humidity: "Humidity", pressure: "Pressure", windSpeed: "Wind Speed" };
const units = { temp: "°C", humidity: "%", pressure: "hPa", windSpeed: "km/h" };
if (value !== undefined && value > limit) {
    msg.payload = `Warning! ${labels[param]} is ${value}${units[param]}. Exceeds limit by ${Math.round((value - limit) * 10) / 10}${units[param]}`;
    return msg;
}
return null;

const w = flow.get("lastWeather");
msg.payload = `The weather in ${w.city} is ${w.description}. Temperature is ${w.temp} degrees celsius. Humidity is ${w.humidity} percent.`;
return msg;
